const query = $('When called by AI Agent').first().json.query || 'unknown';
const data = $input.first().json;

// The HTTP node continues on error; surface a friendly message instead of failing the tool call.
if (data.error || !Array.isArray(data.items)) {
  return [{ json: { response: 'Flipp is unavailable right now for "' + query + '" — try again in a minute.' } }];
}

const items = (data.items || []).slice(0, 20);

if (items.length === 0) {
  return [{ json: { response: 'No deals found for "' + query + '" this week.' } }];
}

const sorted = items.slice().sort(function(a, b) {
  return (a.current_price || 999) - (b.current_price || 999);
});

const seen = {};
const formatted = [];

for (const item of sorted) {
  if (!item.name) continue;

  const store = item.merchant_name || item.merchant || 'unknown store';
  const key = item.name.toLowerCase() + '|' + store.toLowerCase();
  if (seen[key]) continue;
  seen[key] = true;

  // Calculate % off if original_price exists
  let percentOff = null;
  if (item.original_price && item.current_price && item.original_price > item.current_price) {
    percentOff = Math.round(((item.original_price - item.current_price) / item.original_price) * 100);
  }

  formatted.push({
    name: item.name,
    price: item.current_price,
    priceText: item.price_text,
    pricePrefix: item.pre_price_text || null,    // "2 for", "case of"
    priceSuffix: item.post_price_text || null,   // "/lb", "each"
    quantity: item.item_weight || null,          // "500g", "6-pack"
    originalPrice: item.original_price || null,
    percentOff: percentOff,
    saleStory: item.sale_story || null,          // "Save $5", "Limit 2"
    store: store,
    validFrom: item.valid_from ? item.valid_from.substring(0, 10) : null,
    validTo: item.valid_to ? item.valid_to.substring(0, 10) : null
  });

  if (formatted.length >= 12) break;
}

return [{
  json: {
    response: 'Found ' + formatted.length + ' deals for "' + query + '":\n' + JSON.stringify(formatted, null, 2)
  }
}];
